/* ============================================
   HEADING
   One element per outline level, one class per
   type tier. Each tier reads its five tokens
   from tokens-typography.css; the display tiers
   take the display text role and the heading
   tiers the heading role, so a theme that tones
   either tier tones every Heading with it.
   ============================================ */

/* Base */
.ds-heading {
  margin: 0;
  color: var(--color-text-heading);
  overflow-wrap: break-word;
}

/* Tiers: display */
.ds-heading--mega-1 {
  font-family: var(--font-mega-1-family);
  font-size: var(--font-mega-1-size);
  font-weight: var(--font-mega-1-weight);
  line-height: var(--font-mega-1-line-height);
  letter-spacing: var(--font-mega-1-letter-spacing);
  color: var(--color-text-display);
}

.ds-heading--mega-2 {
  font-family: var(--font-mega-2-family);
  font-size: var(--font-mega-2-size);
  font-weight: var(--font-mega-2-weight);
  line-height: var(--font-mega-2-line-height);
  letter-spacing: var(--font-mega-2-letter-spacing);
  color: var(--color-text-display);
}

.ds-heading--display-1 {
  font-family: var(--font-display-1-family);
  font-size: var(--font-display-1-size);
  font-weight: var(--font-display-1-weight);
  line-height: var(--font-display-1-line-height);
  letter-spacing: var(--font-display-1-letter-spacing);
  color: var(--color-text-display);
}

.ds-heading--display-2 {
  font-family: var(--font-display-2-family);
  font-size: var(--font-display-2-size);
  font-weight: var(--font-display-2-weight);
  line-height: var(--font-display-2-line-height);
  letter-spacing: var(--font-display-2-letter-spacing);
  color: var(--color-text-display);
}

.ds-heading--sub-display {
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-display);
}

/* Tiers: heading */
.ds-heading--heading-1 {
  font-family: var(--font-heading-1-family);
  font-size: var(--font-heading-1-size);
  font-weight: var(--font-heading-1-weight);
  line-height: var(--font-heading-1-line-height);
  letter-spacing: var(--font-heading-1-letter-spacing);
  color: var(--color-text-heading);
}

.ds-heading--heading-2 {
  font-family: var(--font-heading-2-family);
  font-size: var(--font-heading-2-size);
  font-weight: var(--font-heading-2-weight);
  line-height: var(--font-heading-2-line-height);
  letter-spacing: var(--font-heading-2-letter-spacing);
  color: var(--color-text-heading);
}

.ds-heading--heading-3 {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-heading);
}

/* Tiers: title in the body face */
.ds-heading--title-body {
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  letter-spacing: var(--font-title-body-letter-spacing);
  color: var(--color-text-heading);
}

/* Tone */
.ds-heading.ds-heading--tone-neutral {
  color: var(--color-text-secondary);
}

/* Wrapping */
.ds-heading--truncate {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.ds-heading--balance {
  text-wrap: balance;
}

/* Alignment */
.ds-heading--align-start {
  text-align: start;
}

.ds-heading--align-center {
  text-align: center;
}

.ds-heading--align-end {
  text-align: end;
}

import React from 'react';
import './Heading.css';

/** A heading type style, named as the type scale names it, from the largest. */
export type HeadingTier =
  | 'mega-1'
  | 'mega-2'
  | 'display-1'
  | 'display-2'
  | 'sub-display'
  | 'heading-1'
  | 'heading-2'
  | 'heading-3'
  | 'title-body';

/** The tier each level wears when no `tier` is passed. */
const LEVEL_TIER: Record<1 | 2 | 3 | 4 | 5 | 6, HeadingTier> = {
  1: 'heading-1',
  2: 'heading-2',
  3: 'heading-3',
  4: 'title-body',
  5: 'title-body',
  6: 'title-body',
};

/** Props owned by Heading itself; everything else falls through to the heading element. */
type HeadingOwnProps = {
  /** The heading's place in the document outline, which sets the element (`h1` to `h6`). Choose it for the outline, never for the size. */
  level?: 1 | 2 | 3 | 4 | 5 | 6;
  /** The type style it wears, apart from `level`, so a card's `h3` can look like a small title and a page's `h1` like a display line. Defaults to the level's own: heading-1 to heading-3 for levels 1 to 3, title-body below. */
  tier?: HeadingTier;
  /** The colour role: `default` takes the tier's own (the display or heading text colour a theme can tone), `neutral` the secondary text colour for a quieter title. */
  tone?: 'default' | 'neutral';
  /** Keep the heading on one line, ending in an ellipsis where it runs out of room. The full text stays in the accessible name. */
  truncate?: boolean;
  /** Balance the lines of a heading that wraps, so the last line is never a lone word. */
  balance?: boolean;
  /** Where the text sits on the line, along the reading direction. */
  align?: 'start' | 'center' | 'end';
  /** The heading's text. */
  children?: React.ReactNode;
  /** Additional CSS classes. */
  className?: string;
};

export interface HeadingProps
  extends HeadingOwnProps,
    Omit<React.ComponentPropsWithRef<'h2'>, keyof HeadingOwnProps> {}

/**
 * A heading in the type scale. `level` sets the element and `tier` the
 * look, chosen apart, so the outline stays correct whatever size a design
 * calls for. Server-renderable.
 */
export function Heading({
  level = 2,
  tier,
  tone = 'default',
  truncate = false,
  balance = false,
  align,
  className = '',
  children,
  ref,
  ...rest
}: HeadingProps) {
  const Tag = `h${level}` as const;
  const resolvedTier = tier ?? LEVEL_TIER[level];
  const classes = [
    'ds-heading',
    `ds-heading--${resolvedTier}`,
    tone !== 'default' && `ds-heading--tone-${tone}`,
    truncate && 'ds-heading--truncate',
    balance && 'ds-heading--balance',
    align && `ds-heading--align-${align}`,
    className,
  ]
    .filter(Boolean)
    .join(' ');
  return (
    <Tag {...rest} ref={ref} className={classes}>
      {children}
    </Tag>
  );
}
